import clsx from 'clsx';
import React, { forwardRef, useContext } from 'react';

import { headingCSS } from './Heading.sty.js';
import { DocumentOutlineContext } from '../core/contexts/DocumentOutline.js';
import type { DataTestId } from '../core/types/data-props.js';
import type { DOMProps } from '../core/types/dom.js';
import type { HeadingLevel, HeadingTag } from '../core/types/heading.js';
import type { StylingProps } from '../core/types/styling-props.js';
import type { WithChildren } from '../core/types/with-children.js';

/** Props used for the Heading component */
export interface HeadingProps
  extends DOMProps,
    WithChildren,
    StylingProps,
    DataTestId {
  /**
   * The visual level of the heading.
   * @defaultValue 1
   */
  level?: HeadingLevel;
  /**
   * The polymorphed HTML tag that determines the semantic level of the heading.
   * @defaultValue 'h1'
   */
  as?: HeadingTag;
}

/**
 * Use the `Heading` to render semantic HTML heading elements (`h1`, `h2`, etc.).
 * The component allows you to independently define both the visual and the semantic level of the heading.
 */
export const Heading = /* @__PURE__ */ forwardRef<
  HTMLHeadingElement,
  HeadingProps
>((props, forwardedRef) => {
  const {
    level,
    children,
    as,
    'data-testid': dataTestId,
    className: consumerClassName,
    style: consumerStyle,
    ...remainingProps
  } = props;

  const contextLevel = useContext(DocumentOutlineContext);
  const visualLevel = level ?? contextLevel ?? 1;
  // semantic level
  const HeadingTag: HeadingTag =
    as ?? (`h${contextLevel ?? visualLevel}` as HeadingTag);

  return (
    <HeadingTag
      ref={forwardedRef}
      data-testid={dataTestId}
      className={clsx(headingCSS({ visualLevel }), consumerClassName)}
      style={consumerStyle}
      {...remainingProps}
    >
      {children}
    </HeadingTag>
  );
});
(Heading as typeof Heading & { displayName: string }).displayName = 'Heading';
